""" Naive PreOp algorithm """
def PreOpN(op: Any, items: Any) -> object {
    k = len(items);
    output = [None] * k;
    output[0] = items[0];
    for i in range(1, k) {
        output[i] = op(output[(i - 1)], items[i]);
    }
    return output;
}

"""For list of object/attrib pairs confirm that the objects have the attrib."""
def has_required(*argv: Any) -> object {
    npairs = len(argv) // 2;
    for i in range(npairs) {
        if not (argv[((2 * i) + 1)] in argv[(2 * i)]) {
            return False;
        }
    }
    return True;
}

