"""
    Check if ip_addr is a IPv4 address. If not it can be IPv6 or an invalid address
    :param ip_addr:
    :return: True iff ip_addr is an IPv4 address, False otherwise
    """
def is_ipv4(ip_addr: Any) -> object {
    no_of_bytes = len(ip_addr.split('.'));
    if (no_of_bytes == 4) {
        return True;
    } else {
        return False;
    }
}

""" Create a protein fasta file from features with amino acid sequences.

    Parameters
    ----------
    feature_list: list
        List of features (each entry is a dict with keys that vary based on available data)
    file_name : str
        Path to output fasta file

    Returns
    -------
    int
        Number of features with amino acid sequences stored in fasta file
    """
def features_to_protein_fasta_file(feature_list: Any, file_name: Any) -> object {
    num_added = 0;
    with open(file_name, 'w') as handle {
        for feature in feature_list {
            if ('aa_sequence' in feature) {
                if (feature['annotation'] == 'PATRIC') {
                    aa_id = 'patric_id';
                } elif (feature['annotation'] == 'RefSeq') {
                    aa_id = 'protein_id';
                } else {
                    raise ValueError('Annotation must be either "PATRIC" or "RefSeq"');
                }
                handle.write(
                    '>{0}\n{1}\n'.format(feature[aa_id], feature['aa_sequence'])
                );
                num_added += 1;
            }
        }
    }
    return num_added;
}

"""
    This function reverse the table

    Parameters :
        tab: the list
    Returns :
        return the reverse table
    """
def reverse_table(tab: Any) -> object {
    for i in range((len(tab) // 2)) {
        tmp = tab[i];
        endVal = len(tab) - i - 1;
        tab[i] = tab[endVal];
        tab[endVal] = tmp;
    }
    return tab;
}

"""
        Given a class and a name, apply python name mangling to it
    :param cls: Class to mangle with
    :param name: Name to mangle
    :return: Mangled name
    """
def _mangle(cls: Any, name: Any) -> object {
    return f"_{cls.__name__}__{name}";
}

"""
    Create a bitmask of `n` ones.
    """
def bitmask(n: Any) -> object {
    return ((1 << n) - 1);
}

"""
    Splits into (head, tail), where head contains no '#' and is max length.
    """
def split_section(url: Any) -> object {
    if ('#' in url) {
        i = url.index('#');
        return (url[:i], url[i:]);
    } else {
        return (url, '');
    }
}

